"""Source-backed two-owner workspace. Editor chrome is not game-window geometry."""
import json
from pathlib import Path


def write_viewer(manifest):
    directory = Path(__file__).parent
    runtime = '\n'.join((directory / n).read_text(encoding='utf-8')
                        for n in ('title_runtime.js', 'workspace_runtime.js'))
